add_action( 'admin_enqueue_scripts', 'dtb_product_mapping_enqueue_assets' );

/** Load Product Relationships assets only for authorized users on its admin page. */
function dtb_product_mapping_enqueue_assets(): void {
	$page = sanitize_key( $_GET['page'] ?? '' ); // phpcs:ignore WordPress.Security.NonceVerification.Recommended
	if ( 'dtb-product-mapping' !== $page || ! current_user_can( 'dtb_manage_product_mapping' ) ) {
		return;
	}

	$asset_dir = __DIR__ . '/assets/';
	$asset_url = plugin_dir_url( __FILE__ ) . 'assets/';
	$css       = $asset_dir . 'dtb-product-relationships.css';
	$js        = $asset_dir . 'dtb-product-relationships.js';

	if ( is_file( $css ) ) {
		wp_enqueue_style( 'dtb-product-relationships', $asset_url . basename( $css ), [], (string) filemtime( $css ) );
	}
	if ( is_file( $js ) ) {
		wp_enqueue_script( 'dtb-product-relationships', $asset_url . basename( $js ), [ 'jquery' ], (string) filemtime( $js ), true );
	}
}

